var fd = tree.root.get_node("/root/Main/FormationsDialog")
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is OptionButton and nd.item_count > 0 and nd.get_item_text(0) == "(Unattached)":
		nd.select(1)
		nd.item_selected.emit(1)
		return true
	for c in nd.get_children():
		q.append(c)
return false

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is CheckBox and str(nd.text).begins_with("Boyz") and not ("Reserves" in str(nd.text)):
		nd.button_pressed = true
		return true
	for c in nd.get_children():
		q.append(c)
return false

var overlay = tree.root.get_node("/root/TutorialOverlay")
var w = overlay.get("_forced_exit_window")
return w != null and is_instance_valid(w) and w.visible

var dlg = tree.root.get_node("/root/Main/TutorialExitConfirmDialog")
var q = [dlg]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is Button and str(nd.text).strip_edges() == "Keep Goin'":
		nd.pressed.emit()
		return true
	for c in nd.get_children(true):
		q.append(c)
return false

var dlg = tree.root.get_node("/root/Main/TutorialExitConfirmDialog")
